#if UNITY_EDITOR
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.Events;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

/// <summary>
/// One-time Editor setup for the in-scene main menu and result navigation.
/// Creates/updates prefab assets and scene references before Play Mode.
/// No UI or gameplay objects are generated by runtime scripts.
/// </summary>
public static class GameFlowUISetup
{
    private const string MainScenePath = "Assets/Scenes/Main.unity";
    private const string MenuPrefabPath = "Assets/Prefabs/UI/UI_Menu.prefab";
    private const string HudPrefabPath = "Assets/Prefabs/UI/UI_HUD.prefab";
    private const string ResultPrefabPath = "Assets/Prefabs/UI/UI_ResultPanel.prefab";

    [MenuItem("Game Jam/Setup Game Flow UI")]
    public static void Setup()
    {
        if (EditorApplication.isPlaying)
        {
            EditorUtility.DisplayDialog("Game Flow UI", "Stop Play Mode before running setup.", "OK");
            return;
        }

        GameObject menuPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(MenuPrefabPath);
        if (menuPrefab == null)
        {
            EditorUtility.DisplayDialog("Game Flow UI", "UI_Menu.prefab was not found.", "OK");
            return;
        }

        ConfigureMainMenuPrefab();
        EnsureResultMainMenuButton();
        WireResultButtons();
        EndingFlowSetup.ConfigureHudPrefab();

        Scene scene = EditorSceneManager.OpenScene(MainScenePath, OpenSceneMode.Single);
        GameManager manager = FindInScene<GameManager>(scene);
        PlayerController player = FindInScene<PlayerController>(scene);
        HUDView hud = FindInScene<HUDView>(scene);
        PauseMenuController pause = FindInScene<PauseMenuController>(scene);
        EndingFlowController endingFlow = FindInScene<EndingFlowController>(scene);

        if (manager == null || player == null || hud == null || endingFlow == null)
        {
            EditorUtility.DisplayDialog(
                "Game Flow UI",
                "Main.unity must contain GameManager, PlayerController, HUDView and the configured story-ending UI.",
                "OK");
            return;
        }

        MainMenuController menuController = FindInScene<MainMenuController>(scene);
        if (menuController == null)
        {
            GameObject menuInstance = PrefabUtility.InstantiatePrefab(menuPrefab, scene) as GameObject;
            if (menuInstance == null)
            {
                EditorUtility.DisplayDialog("Game Flow UI", "Could not place UI_Menu.prefab in Main.unity.", "OK");
                return;
            }

            menuInstance.name = "UI_Menu";
            menuController = menuInstance.GetComponent<MainMenuController>();
        }

        if (menuController == null)
        {
            EditorUtility.DisplayDialog("Game Flow UI", "UI_Menu.prefab has no MainMenuController component.", "OK");
            return;
        }

        SetObjectReference(menuController, "gameManager", manager);
        SetObjectReference(manager, "mainMenuController", menuController);
        SetObjectReference(manager, "pauseMenuController", pause);
        SetObjectReference(manager, "endingFlowController", endingFlow);

        CoverZone[] covers = FindAllInScene<CoverZone>(scene);
        SetObjectArray(manager, "coverZones", covers);

        // Persist the CoverZone -> PlayerController event connection in the scene.
        for (int i = 0; i < covers.Length; i++)
        {
            if (covers[i] == null)
                continue;

            UnityEvent<bool> coverEvent = covers[i].CoverStateChanged;
            for (int listener = coverEvent.GetPersistentEventCount() - 1; listener >= 0; listener--)
                UnityEventTools.RemovePersistentListener(coverEvent, listener);

            UnityEventTools.AddPersistentListener(coverEvent, player.SetInCover);
            EditorUtility.SetDirty(covers[i]);
        }

        menuController.ShowMainMenu();
        hud.ShowMainMenu();
        if (pause != null)
        {
            SetObjectReference(pause, "gameManager", manager);
            pause.HidePanels();
        }

        EditorBuildSettings.scenes = new[]
        {
            new EditorBuildSettingsScene(MainScenePath, true)
        };

        EditorUtility.SetDirty(manager);
        EditorUtility.SetDirty(menuController);
        if (hud != null)
            EditorUtility.SetDirty(hud);

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();

        EditorUtility.DisplayDialog(
            "Game Flow UI",
            "Готово. Main Menu, HUD, результат и связи игровых систем настроены. Main.unity назначена первой сценой сборки.",
            "OK");
    }

    private static void ConfigureMainMenuPrefab()
    {
        const string path = "Assets/Prefabs/UI/UI_StartPanel.prefab";
        GameObject root = PrefabUtility.LoadPrefabContents(path);
        try
        {
            SetText(root.transform, "Title", "LAST EMBER");
            SetText(root.transform, "Detail",
                "Продержись 180 секунд, собирай топливо и укрывайся от порывов ветра.");

            // Enlarge the title, subtitle, control hint below Exit, and all menu labels.
            foreach (Text label in root.GetComponentsInChildren<Text>(true))
            {
                bool enlargeTextRect = label.fontSize == 54 || label.fontSize == 24 || label.fontSize == 18;
                if (label.fontSize == 54)
                    label.fontSize = 108;
                else if (label.fontSize == 24)
                    label.fontSize = 48;
                else if (label.fontSize == 18)
                    label.fontSize = 36;

                RectTransform textRect = label.GetComponent<RectTransform>();
                if (enlargeTextRect && textRect != null && textRect.sizeDelta.sqrMagnitude > 0f)
                    textRect.sizeDelta *= 2f;
            }

            foreach (Button button in root.GetComponentsInChildren<Button>(true))
            {
                RectTransform buttonRect = button.GetComponent<RectTransform>();
                if (buttonRect != null && buttonRect.sizeDelta.x > 0f && buttonRect.sizeDelta.x < 500f)
                    buttonRect.sizeDelta *= 2f;
            }

            PrefabUtility.SaveAsPrefabAsset(root, path);
        }
        finally
        {
            PrefabUtility.UnloadPrefabContents(root);
        }
    }

    private static void SetText(Transform root, string childName, string value)
    {
        Transform child = FindChild(root, childName);
        Text label = child != null ? child.GetComponentInChildren<Text>(true) : null;
        if (label != null)
            label.text = value;
        else
            Debug.LogWarning("GameFlowUISetup: Text component not found for " + childName + ".", root);
    }

    private static void EnsureResultMainMenuButton()
    {
        GameObject root = PrefabUtility.LoadPrefabContents(ResultPrefabPath);
        try
        {
            Transform retry = FindChild(root.transform, "ActionButton");
            if (retry == null)
                throw new System.InvalidOperationException("UI_ResultPanel.prefab has no ActionButton.");

            Transform mainMenu = FindChild(root.transform, "MainMenuButton");
            if (mainMenu == null)
            {
                GameObject copy = Object.Instantiate(retry.gameObject, retry.parent, false);
                copy.name = "MainMenuButton";
                mainMenu = copy.transform;
            }

            RectTransform retryRect = retry.GetComponent<RectTransform>();
            RectTransform menuRect = mainMenu.GetComponent<RectTransform>();
            if (retryRect != null)
                retryRect.anchoredPosition = new Vector2(0f, -135f);
            if (menuRect != null)
                menuRect.anchoredPosition = new Vector2(0f, -215f);

            SetButtonLabel(retry.gameObject, "ЗАНОВО");
            SetButtonLabel(mainMenu.gameObject, "В ГЛАВНОЕ МЕНЮ");
            PrefabUtility.SaveAsPrefabAsset(root, ResultPrefabPath);
        }
        finally
        {
            PrefabUtility.UnloadPrefabContents(root);
        }
    }

    private static void WireResultButtons()
    {
        GameObject root = PrefabUtility.LoadPrefabContents(HudPrefabPath);
        try
        {
            HUDView hud = root.GetComponentInChildren<HUDView>(true);
            Button retry = FindChild(root.transform, "ActionButton")?.GetComponent<Button>();
            Button mainMenu = FindChild(root.transform, "MainMenuButton")?.GetComponent<Button>();

            if (hud == null || retry == null || mainMenu == null)
                throw new System.InvalidOperationException("HUDView or result buttons are missing in UI_HUD.prefab.");

            ClearPersistentListeners(retry.onClick);
            ClearPersistentListeners(mainMenu.onClick);
            UnityEventTools.AddPersistentListener(retry.onClick, hud.OnRetryButtonClicked);
            UnityEventTools.AddPersistentListener(mainMenu.onClick, hud.OnMainMenuButtonClicked);

            PrefabUtility.SaveAsPrefabAsset(root, HudPrefabPath);
        }
        finally
        {
            PrefabUtility.UnloadPrefabContents(root);
        }
    }

    private static void ClearPersistentListeners(UnityEventBase unityEvent)
    {
        for (int i = unityEvent.GetPersistentEventCount() - 1; i >= 0; i--)
            UnityEventTools.RemovePersistentListener(unityEvent, i);
    }

    private static void SetButtonLabel(GameObject buttonRoot, string value)
    {
        Text label = buttonRoot.GetComponentInChildren<Text>(true);
        if (label != null)
            label.text = value;
    }

    private static Transform FindChild(Transform root, string name)
    {
        if (root.name == name)
            return root;

        for (int i = 0; i < root.childCount; i++)
        {
            Transform found = FindChild(root.GetChild(i), name);
            if (found != null)
                return found;
        }

        return null;
    }

    private static T FindInScene<T>(Scene scene) where T : Component
    {
        GameObject[] roots = scene.GetRootGameObjects();
        for (int i = 0; i < roots.Length; i++)
        {
            T found = roots[i].GetComponentInChildren<T>(true);
            if (found != null)
                return found;
        }

        return null;
    }

    private static T[] FindAllInScene<T>(Scene scene) where T : Component
    {
        List<T> values = new List<T>();
        GameObject[] roots = scene.GetRootGameObjects();
        for (int i = 0; i < roots.Length; i++)
            values.AddRange(roots[i].GetComponentsInChildren<T>(true));
        return values.ToArray();
    }

    private static void SetObjectReference(Object target, string propertyName, Object value)
    {
        SerializedObject serialized = new SerializedObject(target);
        SerializedProperty property = serialized.FindProperty(propertyName);
        if (property == null)
            throw new System.InvalidOperationException(
                target.GetType().Name + " has no serialized field named " + propertyName + ".");

        property.objectReferenceValue = value;
        serialized.ApplyModifiedPropertiesWithoutUndo();
    }

    private static void SetObjectArray<T>(Object target, string propertyName, T[] values) where T : Object
    {
        SerializedObject serialized = new SerializedObject(target);
        SerializedProperty property = serialized.FindProperty(propertyName);
        if (property == null)
            throw new System.InvalidOperationException(
                target.GetType().Name + " has no serialized field named " + propertyName + ".");

        property.arraySize = values.Length;
        for (int i = 0; i < values.Length; i++)
            property.GetArrayElementAtIndex(i).objectReferenceValue = values[i];

        serialized.ApplyModifiedPropertiesWithoutUndo();
    }
}
#endif
